// s609 FOX ANIMATIONS for our jointed player (fox-kit jointLimbs: P.fore forearms, P.shin shins). Cutscenes, emotes, story beats.
//   applyPose(THREE, fox, name, t, k)  runs AFTER kit.animFox each frame; t = seconds into the animation (loops), k 0..1 blends in / out.
// Each animation is KEYFRAMES (each key changes only what it lists; n: 1 = start from neutral) + an optional fx(t, D) layer for
// waves, shakes, taps. Paws + feet are TARGETS solved by two-bone IK, so the elbow / knee find their own bend:
//   a: paw offset from the shoulder [out, up, forward] (out = away from the body on that side) · pole: elbow direction
//   l: foot [out, height above ground, forward] · lpole: knee direction · drop / hop: body down / up · lean / twist / roll: body
//   (pivots at the hips) · head [pitch, yaw, roll] · face: mood, mouth 0..1, look (-1 left .. 1 right), lookY (-1 up .. 1 down), blink
//   sweat 0/1 (a drop on the head) · mark '?' / '!' (pops over the head)
//   HANDS: g [left, right] 0 open .. 1 fist · pt [l, r] 1 = index finger stays out (point / finger guns) · spread (open-finger spread)
//   palm [l, r] which way the PALM faces in body space [out, up, forward] (default: toward the thigh) · wr [l, r] wrist [flex, side bend]
//   tu thumb up · op thumb opposed (grabbing) · fc [l, r] per-finger curl [index, middle, ring, pinky] used where fcw is 1
// NO PAWS IN THE BODY: every paw target is pushed out of the torso, hips, head and muzzle (+ paw radius) before solving; if the
// elbow or forearm would still cut through, the elbow swings outward and the solve repeats. u.poseClear reports the worst overlap.
const D0 = [0.06, -0.62, 0.06], DP = [0.35, -1, -0.5], DL = [0, 0.05, 0.02], DLP = [0, 0, 1];
const NEU = { a: [D0, D0], pole: [DP, DP], l: [DL, DL], lpole: [DLP, DLP], drop: 0, hop: 0, lean: 0, twist: 0, roll: 0, head: [0, 0, 0], mouth: 0, look: 0, lookY: 0, blink: 0, sweat: 0, mark: '', mood: 'determined', g: [0.32, 0.32], pt: [0, 0], spread: 1,
  palm: [[-1, 0, -0.2], [-1, 0, -0.2]], wr: [[0.12, 0], [0.12, 0]], tu: [0, 0], op: [0, 0], fc: [[0.3, 0.3, 0.3, 0.3], [0.3, 0.3, 0.3, 0.3]], fcw: [0, 0], sh: [0, 0], hp: [0.11, 0.11], ext: [0, 0], mp: null, hl: '', hr: '', rif: 0, fwd: 0, rb: 0, rbx: 0, bx: 0, bz: 0, ft: [0, 0] };
export const neutralD = () => { const o = {}; for (const k in NEU) o[k] = clone(NEU[k]); return o; };   // a fresh deep copy every call (NEU must never be mutated)   // s612: hosts that build their own pose each frame (FOX DANCE) start from this and call applyD
const IN = [-1, 0, -0.2], FWD = [0, 0.05, 1], UPP = [0.15, 1, 0.25], DNP = [-0.3, -1, 0.1], BACK = [0, 0, -1];
const two = v => [v, v];
const DLR = { mood: 'determined', lean: 0.1 }, SEAT = { l: two([0.03, 0.44, 0.2]), lpole: two([0, 0.3, 1]), lean: 0.06 };   // s610 casino
const cl01 = x => Math.max(0, Math.min(1, x)), sm = e => e * e * (3 - 2 * e);
const EASE = { io: sm, out: e => 1 - Math.pow(1 - e, 3), in: e => e * e * e, back: e => { const c = 1.7, x = e - 1; return 1 + (c + 1) * x * x * x + c * x * x; }, lin: e => e };
const win = (t, a, b, f = 0.2) => sm(cl01((t - a) / f)) * sm(cl01((b - t) / f));
const GUARD = { a: [[0.0, 0.12, 0.48], [0.02, 0.06, 0.44]], pole: two([0.45, -1, -0.05]), l: [[0.06, 0.05, 0.18], [0.06, 0.05, -0.16]], drop: 0.07, head: [0.12, 0, 0], twist: -0.15, mood: 'determined', g: [1, 1], palm: two([-1, 0, 0.15]), wr: two([0, 0]) };
const FOLD = { a: [[-0.4, -0.2, 0.42], [-0.36, -0.13, 0.5]], pole: two([1, -0.2, 0]), palm: two([0, -0.3, -1]), wr: two([0.1, 0]) };
